    def cleanup(self, name, identifier):
        failure = False
        try:
            operation = self.api.json('DELETE', 'https://batch.googleapis.com/v1/' + name, allow_missing=True)
            if operation is not None:
                expected = self.parent + '/operations/'
                op = operation.get('name')
