import base64
import json
import ipaddress
from pathlib import Path
import re
import subprocess
import shlex
import sys


def run(argv):
    if argv and argv[0]=='/usr/bin/docker':
        # An operator's saved Docker context must never redirect this native
        # host inspection to another daemon, even with a scrubbed environment.
        argv=[argv[0],'--host','unix:///var/run/docker.sock',*argv[1:]]
