import os
import socket
import sys
from pathlib import Path
import threading
import time
sys.path.insert(0,str(Path(__file__).resolve().parent))
from invoice_document import PdfDocument,DocumentError

LIMIT=10000000

class ParserServer(ThreadingHTTPServer):
    daemon_threads=True
    request_queue_size=16
